#!/usr/bin/env node
// Generates src/ui/tokens.css and the YAML front matter of DESIGN.md from
// src/ui/tokens.json (DTCG). Run `npm run gen:tokens`; CI runs it with --check
// and fails when a generated file is out of date.
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const SRC = path.join(root, "src/ui/tokens.json");
const CSS = path.join(root, "src/ui/tokens.css");
const DESIGN = path.join(root, "DESIGN.md");
const check = process.argv.includes("--check");

const tree = JSON.parse(fs.readFileSync(SRC, "utf8"));

/** Flatten to [{ path: ["color","stone","50"], value, type }]. */
function flatten(node, trail = [], inheritedType) {
  const out = [];
  const type = node.$type ?? inheritedType;
  for (const [key, child] of Object.entries(node)) {
    if (key.startsWith("$")) continue;
    if (child && typeof child === "object" && "$value" in child) {
      out.push({ path: [...trail, key], value: child.$value, type: child.$type ?? type });
    } else if (child && typeof child === "object") {
      out.push(...flatten(child, [...trail, key], type));
    }
  }
  return out;
}

const tokens = flatten(tree);
const byPath = new Map(tokens.map((t) => [t.path.join("."), t]));
const ALIAS = /^\{([^}]+)\}$/;

function resolve(value, seen = new Set()) {
  const m = typeof value === "string" ? value.match(ALIAS) : null;
  if (!m) return value;
  if (seen.has(m[1])) throw new Error(`Alias cycle at ${m[1]}`);
  const target = byPath.get(m[1]);
  if (!target) throw new Error(`Unknown alias ${value}`);
  return resolve(target.value, new Set([...seen, m[1]]));
}

const cssName = (p) => `--rb-${p.join("-")}`;

function cssValue(t) {
  const m = typeof t.value === "string" ? t.value.match(ALIAS) : null;
  if (m) return `var(${cssName(m[1].split("."))})`;
  return String(t.value);
}

const css =
  "/* Generated by scripts/build-tokens.mjs from src/ui/tokens.json. Do not edit. */\n" +
  ":root {\n" +
  tokens.map((t) => `  ${cssName(t.path)}: ${cssValue(t)};`).join("\n") +
  "\n}\n";

const q = (s) => `"${String(s).replace(/"/g, '\\"')}"`;
const group = (prefix) => tokens.filter((t) => t.path[0] === prefix);
const frontMatter = [
  "---",
  "# Generated by scripts/build-tokens.mjs from src/ui/tokens.json. Edit the JSON, not this block.",
  "name: RawiBumi",
  "description: Light stone panels around a warm graphite drawing workspace. The TSE sun palette is a hint for selection and status only; drawings speak ISO 3098 lettering.",
  "colors:",
  ...[...group("color"), ...group("role")].map(
    (t) => `  ${t.path[0] === "role" ? "role-" : ""}${t.path.slice(1).join("-")}: ${q(resolve(t.value))}`
  ),
  "typography:",
  ...group("font").map((t) => `  ${t.path[1]}:\n    fontFamily: ${q(t.value)}`),
  "  sizes:",
  ...group("size").map((t) => `    ${t.path[1]}: ${q(t.value)}`),
  "rounded:",
  ...group("radius").map((t) => `  ${t.path[1]}: ${q(t.value)}`),
  "spacing:",
  ...group("space").map((t) => `  s${t.path[1]}: ${q(t.value)}`),
  "motion:",
  ...group("motion").map((t) => `  ${t.path[1]}: ${q(t.value)}`),
  "---",
  ""
].join("\n");

const design = fs.readFileSync(DESIGN, "utf8").replace(/\r\n/g, "\n");
const fm = design.match(/^---\n(?:[\s\S]*?\n)?---\n/);
if (!fm) throw new Error("DESIGN.md must start with a --- front matter block");
const nextDesign = frontMatter + design.slice(fm[0].length);

const outputs = [
  [CSS, css],
  [DESIGN, nextDesign]
];

let stale = 0;
for (const [file, content] of outputs) {
  // Compare with LF line endings so a Windows checkout (core.autocrlf) does not read as stale.
  const current = fs.existsSync(file) ? fs.readFileSync(file, "utf8").replace(/\r\n/g, "\n") : "";
  if (current === content) continue;
  if (check) {
    console.error(`Out of date: ${path.relative(root, file)} (run npm run gen:tokens)`);
    stale++;
  } else {
    fs.writeFileSync(file, content);
    console.log(`Wrote ${path.relative(root, file)}`);
  }
}
if (check && stale) process.exit(1);
if (check) console.log(`Tokens up to date (${tokens.length} tokens).`);
